steps = [
    step("三次握手在线上(lo0):SYN 的序号是客户端的初始序号 ISN 1721712522;SYN-ACK 的序号是服务端自己的 ISN 2719271520,确认号 1721712523 = 客户端 ISN + 1;第三个包 ACK 的序号 1721712523 = 客户端 ISN + 1,确认号 2719271521 = 服务端 ISN + 1。三个“= +1”的关系全部验证成立:SYN 占一个序号,所以每方都用对方 ISN + 1 作为确认号。lo0 上 connect() 用时 4758 µs;en0 到 example.com 的 connect() 用了 176.7 ms,抓包里 SYN → SYN-ACK 间隔 175.2 ms,正好是一个往返,connect 返回的时刻与收到 SYN-ACK 基本同时。", t=tl(S(1)), mark=lidx(S(1), 'lo0 SYN:', 'lo0 SYN-ACK:', 'lo0 ACK:', '关系:'), done=lidx(S(1), 'lo0 上 connect()', 'en0 到 example.com'), b=bars([['lo0 · connect()', 4.758, '4.758 ms'], ['en0 · connect()', 176.7, '176.7 ms'], ['en0 · SYN → SYN-ACK', 175.2, '175.2 ms']], 176.7, mark=[1, 2], done=[0]), kv=KV([['SYN', '序号 = 客户端 ISN'], ['SYN-ACK', '序号 = 服务端 ISN,确认号 = 客户端 ISN + 1'], ['ACK', '序号 = 客户端 ISN + 1,确认号 = 服务端 ISN + 1'], ['connect()', '= 一个往返']], ['connect()'])),
    step("初始序号(ISN):在 lo0 上连续建立 2000 个连接,抓到 2000 个 SYN,2000 个 ISN 互不相同,范围 561029 ~ 4289965881(32 位空间是 0 ~ 4294967295)。相邻两个连接的 ISN 之差(模 2^32)小于 2^20 的有 0 个——若是按时钟递增几乎全部都会很小;ISN 的均值是 0.493 × 2^32,接近均匀随机的 0.5;把 32 位空间分成 16 份,每份的个数是 132、119、134、160、123、117、111、132、118、117、117、125、115、114、148、118,约 125 上下。也就是说本机的 ISN 是随机分布的。老系统用 4 微秒一次的时钟递增 ISN,容易被猜到后伪造连接,RFC 6528 要求加哈希随机化。", t=tl(S(2)), mark=lidx(S(2), '相邻两个连接', '把 32 位空间分 16 份'), done=lidx(S(2), '抓到 2000 个 SYN', '老系统用'), b=bars([['不同的 ISN', 2000, '2000 / 2000'], ['相邻差值 < 2^20 的个数', 0, '0']], 2000, mark=[1], done=[0]), kv=KV([['2000 个连接', '2000 个不同的 ISN'], ['均值', '0.493 × 2^32(均匀随机 ≈ 0.5)'], ['相邻之差 < 2^20', '0 个:不是时钟递增'], ['16 等分', '每份约 125(111~160)']], ['相邻之差 < 2^20'])),
    step("SYN 没有回应时怎么重传:连接一个会丢弃 SYN 的地址(example.com 的 81 端口),抓 25 秒。net.inet.tcp.keepinit = 75000(连接建立的总超时 75 秒),本机没有 syn_retries 参数。25 秒内抓到 9 个 SYN,发送时刻(秒)是 0.0、1.0、2.0、3.01、4.01、5.01、7.01、11.01、19.01:前 6 个间隔固定 1 秒,之后 2、4、8 秒指数退避。所有 SYN 序号相同(是重传不是新连接);第一个 SYN 带 ECN 标志,其余 8 个都不带——ECN 协商没有回应,后续重传就退回不带 ECN 的普通 SYN。connect 在设定的 25 秒后以 TimeoutError 结束(系统本身的上限是 75 秒)。", t=tl(S(3)), mark=lidx(S(3), '25 秒的超时里', '相邻 SYN 的间隔'), done=lidx(S(3), 'net.inet.tcp.keepinit', '(net.inet.tcp.syn_retries'), b=bars([['SYN #1', 0, '0.0 s'], ['SYN #6', 5.01, '5.01 s'], ['SYN #7', 7.01, '7.01 s'], ['SYN #8', 11.01, '11.01 s'], ['SYN #9', 19.01, '19.01 s']], 19.01, mark=[2, 3, 4], done=[0, 1]), kv=KV([['前 6 个 SYN', '间隔固定 1 秒(0~5 秒)'], ['之后', '间隔 2、4、8 秒(7、11、19 秒)'], ['ECN', '只有第 1 个 SYN 带'], ['连接超时', 'keepinit = 75 秒']], ['之后'])),
    step("握手顺便协商的参数。本机 lo0:我的 SYN 和对方 SYN-ACK 的选项相同,MSS 16344、窗口缩放 6、时间戳、SACK。example.com:我的 SYN 是 MSS 1460、窗口缩放 6;对方 SYN-ACK 是 MSS 1400、窗口缩放 13、时间戳、SACK,标志 ACK+SYN+ECE(ECE 表示接受 ECN)。另一个公网主机:对方 MSS 1452、窗口缩放 13、时间戳、SACK。双方各自在 SYN / SYN-ACK 里通告自己的 MSS、窗口缩放、是否支持时间戳和 SACK;只有双方都带了某个选项,这个功能才会启用——窗口缩放要求两边都带,否则都不启用。", t=tl(S(4)), mark=lidx(S(4), '本机 lo0:', 'example.com:', '另一个公网主机:'), done=lidx(S(4), '双方各自在'), kv=KV([['lo0', '双方 MSS 16344,缩放 6'], ['example.com', '对方 MSS 1400,缩放 13'], ['另一个公网主机', '对方 MSS 1452,缩放 13'], ['启用条件', '两边的 SYN 都带了才启用']], ['启用条件'])),
    step("谁在什么时候“完成”:netlab 给 lo0 加 50 ms 单向延迟(往返 100 ms),客户端 connect() 在 101 ms 时返回(一个往返:SYN → SYN-ACK),服务端 accept() 在 151 ms 时返回——要等到客户端的第三个 ACK 到达,再过半个往返。所以客户端先认为连接建立,服务端后认为;如果第三个 ACK 丢了,客户端会以为已连接并开始发数据,服务端还在 SYN_RCVD(下一篇状态机再看)。", t=tl(S(5)), mark=lidx(S(5), '往返 100 ms'), done=lidx(S(5), '所以客户端先认为'), b=bars([['客户端 connect() 返回', 101, '101 ms'], ['服务端 accept() 返回', 151, '151 ms']], 151, mark=[1], done=[0]), kv=KV([['往返 100 ms', '客户端 101 ms 完成'], ['服务端', '151 ms 才 accept 到'], ['差', '半个往返 = 等第三个 ACK']], ['差'])),
]
